INSERT OR IGNORE INTO posts(id,title,slug,excerpt,content_html,featured_image,author_user_id,category_id,status,published_at,seo_title,seo_description,canonical_url,og_image,robots,schema_json,focus_keyword,content_type,cluster_slug,primary_keyword,search_intent,seo_priority,reviewed_at,reviewed_by,sources_json,experience_note,featured,reading_time,created_at,updated_at) VALUES ('post-primeiros-passos-web','Primeiros passos para criar seu primeiro site','primeiros-passos-web','Um guia simples para entender HTML, CSS, JavaScript e publicar seu primeiro projeto na web.','<p>Criar um site pode parecer complicado no começo, mas você não precisa aprender tudo de uma vez.</p><h2>1. Comece pelo HTML</h2><p>O HTML define a estrutura da página: títulos, textos, links, imagens e outros elementos.</p><pre><code>&lt;h1&gt;Meu primeiro site&lt;/h1&gt;
&lt;p&gt;Estou começando minha jornada na web.&lt;/p&gt;</code></pre><h2>2. Use CSS para criar o visual</h2><p>O CSS controla cores, espaçamentos, tipografia e responsividade.</p><pre><code>body {
  font-family: sans-serif;
  line-height: 1.6;
}</code></pre><h2>3. Adicione JavaScript quando precisar de interação</h2><p>JavaScript permite criar menus, filtros, formulários e outras experiências interativas.</p><h2>4. Publique seu projeto</h2><p>Depois de construir e testar, você pode colocar o site online usando GitHub e uma plataforma de hospedagem como Cloudflare Pages.</p><h2>Próximo passo</h2><p>Agora que você conhece a base, o próximo objetivo é criar uma página completa e publicar seu primeiro projeto.</p>',NULL,'user-admin-seed','cat-programacao','published','2026-09-01T12:00:00Z',NULL,NULL,NULL,NULL,'index,follow',NULL,NULL,'cluster','fundamentos-web','como criar um site','informacional','alta','2026-09-02','Equipe editorial Dejotacode','[]','Conteúdo produzido com foco em aplicação prática, linguagem acessível e atualização editorial contínua.',1,6,datetime('now'),datetime('now'));
