INSERT OR IGNORE INTO posts(id,title,slug,excerpt,content_html,featured_image,author_user_id,category_id,status,published_at,seo_title,seo_description,canonical_url,og_image,robots,schema_json,focus_keyword,content_type,cluster_slug,primary_keyword,search_intent,seo_priority,reviewed_at,reviewed_by,sources_json,experience_note,featured,reading_time,created_at,updated_at) VALUES ('post-publicar-site','Como publicar um site pela primeira vez','publicar-site','Passo a passo para sair do computador local e colocar um projeto web acessível pela internet.','<p>Publicar um site envolve três etapas: preparar o projeto, versionar o código e configurar a hospedagem.</p><h2>1. Teste localmente</h2><p>Confirme que o projeto funciona antes de publicar.</p><h2>2. Envie para um repositório</h2><p>Use Git para manter histórico e enviar o projeto para o GitHub.</p><h2>3. Configure o deploy</h2><p>Conecte o repositório a uma plataforma de hospedagem e faça o primeiro deploy.</p>',NULL,'user-admin-seed','cat-tutoriais-guias','published','2026-08-24T12:00:00Z',NULL,NULL,NULL,NULL,'index,follow',NULL,NULL,'cluster','tutoriais-resolutivos','como publicar um site','informacional','alta','2026-09-02','Equipe editorial Dejotacode','[]','Conteúdo produzido com foco em aplicação prática, linguagem acessível e atualização editorial contínua.',0,7,datetime('now'),datetime('now'));
