INSERT OR IGNORE INTO posts(id,title,slug,excerpt,content_html,featured_image,author_user_id,category_id,status,published_at,seo_title,seo_description,canonical_url,og_image,robots,schema_json,focus_keyword,content_type,cluster_slug,primary_keyword,search_intent,seo_priority,reviewed_at,reviewed_by,sources_json,experience_note,featured,reading_time,created_at,updated_at) VALUES ('post-primeiro-freelance','Como começar no freelancing sem complicar','primeiro-freelance','Um roteiro inicial para escolher uma habilidade, montar uma oferta simples e buscar o primeiro cliente.','<p>Começar como freelancer fica mais fácil quando você transforma uma habilidade em uma oferta clara.</p><h2>Escolha um serviço</h2><p>Comece com algo que você consegue entregar bem: criação de páginas, edição, design, automação ou suporte técnico.</p><h2>Monte uma oferta simples</h2><p>Explique o problema que você resolve, o que entrega e qual é o próximo passo para contratar.</p>',NULL,'user-admin-seed','cat-renda-digital','published','2026-08-28T12:00:00Z',NULL,NULL,NULL,NULL,'index,follow',NULL,NULL,'cluster','primeira-renda-digital','como ser freelancer','informacional','alta','2026-09-02','Equipe editorial Dejotacode','[]','Conteúdo produzido com foco em aplicação prática, linguagem acessível e atualização editorial contínua.',0,5,datetime('now'),datetime('now'));
